**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <map>
#include <vector>
#include <algorithm>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("zamowienia.txt");
    map<string, int> przychod;
    string produkt;
    int ilosc, cena;
    int total = 0;
    while (plik >> produkt >> ilosc >> cena) {
        przychod[produkt] += ilosc * cena;
        total += ilosc * cena;
    }

    vector<pair<int, string>> ranking;
    for (auto &p : przychod) {
        ranking.push_back({p.second, p.first});
    }
    sort(ranking.begin(), ranking.end(), [](auto &a, auto &b) {
        return a.first > b.first;
    });

    cout << "a) Przychod wg produktu (malejaco):" << endl;
    for (auto &r : ranking) {
        cout << "   " << r.second << ": " << r.first << endl;
    }

    cout << endl << "b) Najlepszy produkt: " << ranking[0].second << " (" << ranking[0].first << ")" << endl;

    double udzial = ranking[0].first * 100.0 / total;
    cout << endl << "c) Udzial: " << fixed << setprecision(2) << udzial << "%" << endl;
    return 0;
}
```

